:root {
  --font-family: var(--font-inter), sans-serif;
  --primary: oklch(62.3% 0.214 259.815);
  --primary-foreground: oklch(98.5% 0 0);
}

html,
body {
  font-family: var(--font-family), sans-serif;
  font-size: 14px;
  color: var(--text-primary);
  background-color: var(--surface-raised);
  width: 100%;
  min-height: 100vh;
}

html[style*="padding-right"] {
  padding-right: 0 !important;
}

::-webkit-scrollbar {
  width: 15px;
  background: transparent;
}

::-webkit-scrollbar-track {
  border: 7px solid rgba(0, 0, 0, 0);
  background-color: var(--border-default);
  background-clip: padding-box;
}

::-webkit-scrollbar-thumb {
  border: 7px solid rgba(0, 0, 0, 0);
  background-color: var(--text-disabled);
  border-radius: var(--border-radius-full);
  background-clip: padding-box;
}

::-webkit-scrollbar-thumb:hover {
  border: 4px solid rgba(0, 0, 0, 0);
  background-clip: padding-box;
}

/* Fix autofill background color to match dark theme */
input:-webkit-autofill,
input:-webkit-autofill:hover,
input:-webkit-autofill:focus,
input:-webkit-autofill:active,
textarea:-webkit-autofill,
textarea:-webkit-autofill:hover,
textarea:-webkit-autofill:focus,
select:-webkit-autofill,
select:-webkit-autofill:hover,
select:-webkit-autofill:focus {
  -webkit-box-shadow: 0 0 0 1000px var(--background-color) inset !important;
  transition: color 5000s ease-in-out 0s;
}

/* Code snippet textareas */
.code-textarea textarea {
  min-height: 100px;
}

/* rrweb-player overrides */
.rr-controller__btns {
  gap: 8px;
}

[data-theme="dark"] .rr-controller__btns button {
  color: black;
}

[data-theme="dark"] .rr-controller__btns .label {
  color: black;
}

